
CREATE TABLE "public"."QuickSqlDefaultsRow" ("Id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "Label" VARCHAR(16) NULL DEFAULT '新行', "Active" BOOLEAN NOT NULL DEFAULT TRUE, "Reserved" INTEGER NOT NULL DEFAULT 7, "Ratio" DOUBLE PRECISION NOT NULL DEFAULT 0.5, "Amount" NUMERIC(18,4) NOT NULL, "Bare" TEXT NULL, CONSTRAINT "PK_QuickSqlDefaultsRow" PRIMARY KEY ("Id"))
